import{_ as i,o as a,c as t,ag as e}from"./chunks/framework.DEqXEGcv.js";const c=JSON.parse('{"title":"Spawning Children","description":"","frontmatter":{},"headers":[],"relativePath":"composition/spawning-children.md","filePath":"composition/spawning-children.md"}'),n={name:"composition/spawning-children.md"};function l(h,s,p,d,r,o){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="spawning-children" tabindex="-1">Spawning Children <a class="header-anchor" href="#spawning-children" aria-label="Permalink to &quot;Spawning Children&quot;">​</a></h1><p>Children are instances that belong to a parent. They can be created in two ways: via SPAWN in a MUTATE clause during a transition, or externally with a standalone SPAWN command.</p><h2 id="spawn-in-mutate" tabindex="-1">SPAWN in MUTATE <a class="header-anchor" href="#spawn-in-mutate" aria-label="Permalink to &quot;SPAWN in MUTATE&quot;">​</a></h2><p>The most common pattern is spawning a child as part of a parent&#39;s transition. The <code>MUTATE</code> clause assigns the spawned instance to a child slot:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">paid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fulfilled {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  GUARD  : ALL(items, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">STATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> confirmed)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  MUTATE : shipment </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SPAWN Shipment { order: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>When this transition fires:</p><ol><li>A new Shipment instance is created in its initial state (<code>created</code>)</li><li>The Shipment&#39;s <code>parent_id</code> is set to the Order&#39;s ID</li><li>The Shipment&#39;s <code>parent_machine</code> is set to <code>&quot;Order&quot;</code></li><li>The Shipment&#39;s <code>order</code> data field is set to the Order instance (via <code>SELF</code>)</li><li>The <code>shipment</code> child slot on the Order now references this instance</li></ol><h3 id="self-keyword" tabindex="-1">SELF Keyword <a class="header-anchor" href="#self-keyword" aria-label="Permalink to &quot;SELF Keyword&quot;">​</a></h3><p><code>SELF</code> refers to the current (parent) instance. It is commonly passed to the child so the child has a reference back:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MUTATE : shipment </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SPAWN Shipment { order: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h3 id="empty-data-blocks" tabindex="-1">Empty Data Blocks <a class="header-anchor" href="#empty-data-blocks" aria-label="Permalink to &quot;Empty Data Blocks&quot;">​</a></h3><p>SPAWN always requires braces, even when passing no initial data:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MUTATE : tracker </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SPAWN Tracker {}</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>SPAWN Tracker</code> without <code>{}</code> is a syntax error. Always include the braces.</p></div><h3 id="multiple-spawns" tabindex="-1">Multiple Spawns <a class="header-anchor" href="#multiple-spawns" aria-label="Permalink to &quot;Multiple Spawns&quot;">​</a></h3><p>A single transition can spawn multiple children:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">approved </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> active {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  MUTATE : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">primary</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SPAWN Account { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;primary&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  MUTATE : savings </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SPAWN Account { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;savings&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="external-spawn" tabindex="-1">External SPAWN <a class="header-anchor" href="#external-spawn" aria-label="Permalink to &quot;External SPAWN&quot;">​</a></h2><p>Children can also be spawned outside of a transition using the standard SPAWN command. The engine associates the child with its parent based on the machine definitions:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SPAWN LineItem {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  product: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Widget&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  quantity: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  price: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">99</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>When spawning a child externally, the parent ID must be provided so the engine can establish the relationship. The server API accepts the parent context:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-RVLEZ" id="tab-rDvKDv8" checked><label data-title="curl" for="tab-rDvKDv8">curl</label><input type="radio" name="group-RVLEZ" id="tab-yHp1jMz"><label data-title="REPL" for="tab-yHp1jMz">REPL</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:4200/execute</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;smql&quot;: &quot;SPAWN LineItem { product: \\&quot;Widget\\&quot;, quantity: 3, price: 9.99 }&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;parent_id&quot;: &quot;01J5X7K2P3Q4R5S6T7U8V9W0XY&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SPAWN LineItem { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">product:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Widget&quot;,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quantity:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> price:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9.99</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> }</span></span></code></pre></div></div></div><h2 id="spawning-into-list-vs-optional" tabindex="-1">Spawning into LIST vs OPTIONAL <a class="header-anchor" href="#spawning-into-list-vs-optional" aria-label="Permalink to &quot;Spawning into LIST vs OPTIONAL&quot;">​</a></h2><p>The cardinality type determines how many children can exist:</p><h3 id="list-children" tabindex="-1">LIST Children <a class="header-anchor" href="#list-children" aria-label="Permalink to &quot;LIST Children&quot;">​</a></h3><p>A <code>LIST</code> slot accepts multiple children. Each SPAWN adds to the list:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CHILDREN {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  items : LIST(LineItem) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>You can spawn as many LineItem children as needed (subject to MAX constraints if defined).</p><h3 id="optional-children" tabindex="-1">OPTIONAL Children <a class="header-anchor" href="#optional-children" aria-label="Permalink to &quot;OPTIONAL Children&quot;">​</a></h3><p>An <code>OPTIONAL</code> slot accepts at most one child:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CHILDREN {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  shipment : OPTIONAL(Shipment)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>If a Shipment already exists for this Order, attempting to spawn another will fail.</p><h2 id="spawn-validation" tabindex="-1">Spawn Validation <a class="header-anchor" href="#spawn-validation" aria-label="Permalink to &quot;Spawn Validation&quot;">​</a></h2><p>When spawning a child, the engine validates:</p><ol><li><strong>Parent exists</strong> -- the parent instance must exist and not be in a terminal state</li><li><strong>Machine match</strong> -- the child machine must be declared in the parent&#39;s CHILDREN block</li><li><strong>Cardinality</strong> -- LIST respects MIN/MAX; OPTIONAL allows at most one</li><li><strong>Data constraints</strong> -- all REQUIRED fields present, types match, constraints satisfied</li><li><strong>PARENT declaration</strong> -- the child machine must declare the correct PARENT type</li></ol><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>Spawned children begin in their initial state, just like any other instance. They receive a trail entry at sequence 0 recording the spawn event. From that point, they transition independently -- unless the parent uses <a href="./cascade.html">CASCADE</a> or the child uses <a href="./signal-parent.html">SIGNAL PARENT TO</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Children are independent instances with their own state, data, version, and trail. Composition provides the relationship and coordination primitives, but each child has its own lifecycle.</p></div>`,38)])])}const E=i(n,[["render",l]]);export{c as __pageData,E as default};
